                      <span className="upd-pop-ico" aria-hidden="true">
                        <ArrowUp size={15} strokeWidth={2.6} />
                      </span>
                      <div className="upd-pop-title">
                        <b>
                          {t("update.available", "发现新版本")} v{pendingUpdate.latest}
