                    <footer className="upd-pop-ft">
                      <button type="button" className="btn ghost btn-sm" onClick={() => setUpdPop(false)}>
                        {t("update.later", "稍后")}
                      </button>
                      <button
                        type="button"
                        className="btn primary btn-sm"
                        onClick={() => {
                          setUpdPop(false);
                          setAutoUpdate(pendingUpdate);
