                      >
                        {t("update.viewDetail", "查看更新")}
                      </button>
                    </footer>
                  </div>
                ) : null}
              </div>
            ) : null}
          </div>
          <div className="header-actions">
            {/* v13：系统时间从右栏卡片收进顶栏——时间属窗口级信息，
                不值得在右栏独占一张卡（那会让右栏超出一屏）。 */}
            <div className="header-search">
              <svg
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                width="16"
                height="16"
