                                {isGroup ? <i>{t("proxies.groupTag", "组")}</i> : null}
                                {isSystemOutbound(n) ? <i>{t("proxies.systemTag", "系统")}</i> : null}
                              </span>
                            </span>
                            <span
                              className={`px-card-delay ${cls}`}
                              title={(() => {
                                const h = delayHistory[n];
                                if (h?.length) {
                                  return h
