                              <span className="px-spark" aria-hidden="true">
                                {hist.map((h, i) => {
                                  const hgt =
                                    h.ms > 0
                                      ? Math.max(2, Math.min(9, Math.round((h.ms / maxMs) * 9)))
                                      : 1;
                                  return (
                                    <span
                                      key={i}
                                      className={`px-spark-bar ${delayDotClass(h.ms)}`}
                                      style={{ height: `${hgt}px` }}
                                    />
                                  );
                                })}
                              </span>
                            )}
                          </button>
                        );
                      })}
                    </div>
