                      </div>
                    );
                  })()}
                </div>

              {/* 保留挂载（hidden 切换）：测试结果切页不丢 */}
              <div className="pane" hidden={tab !== "tests"}>
                <TestsPage running={running} onToast={showToast} />
              </div>

              <div className="pane" hidden={tab !== "settings"}>
                <SettingsPanel
                    running={running}
                    mixedPort={mixedPort}
                    controller={controller}
                    version={version}
                    autoPick={autoPick}
                    themeMode={themeMode}
                    onThemeChange={changeTheme}
                    onToast={showToast}
                    onUpdateFound={(info) => {
                      setAutoUpdate(info);
                      setPendingUpdate(info);
                      setUpdPct(-1);
                      setUpdBusy(false);
                      setUpdMsg("");
                    }}
                    updateNotice={pendingUpdate}
                    onBusy={setBusy}
                    onPorts={handlePorts}
                    onPrefs={handlePrefs}
                    onRefresh={refresh}
                    onCoreChange={setActiveCore}
                />
              </div>
            </main>
          </div>

